text:
{
  "questions": [
    {
      "n": 1,
      "start": "Weshalb verkehren entgegen der Zusage",
      "end": "nicht garantiert werden kann?"
    },
    {
      "n": 2,
      "start": "Entgegen den Aussagen von 2014 sollen",
      "end": "festgestellt wurde?"
    },
    {
      "n": 3,
      "start": "Wer ist dafür verantwortlich, dass die Zusage",
      "end": "eingehalten werden kann?"
    },
    {
      "n": 4,
      "start": "Auf der Linie 6 kommt es wiederholt zu starken",
      "end": "verbessern?"
    },
    {
      "n": 5,
      "start": "Weshalb verkehren auch an Tagen und Tageszeiten",
      "end": "alte Tramtraktionen?"
    },
    {
      "n": 6,
      "start": "Kann sich der Gemeinderat dafür einsetzen, falls kein",
      "end": "alternierend eingesetzt werden?"
    },
    {
      "n": 7,
      "start": "Ist der Gemeinderat bereit, die BVB aufzufordern, zu",
      "end": "ausschliesslich mit Niederflurtrams zu bedienen."
    }
  ],
  "answers": [
    {
      "n": 1,
      "start": "Wie viele Altfahrzeuge auf dem BVB-Liniennetz unterwegs sind, hängt jeweils von der",
      "end": "nicht immer verhindert werden kann."
    },
    {
      "n": 2,
      "start": "Bei der letzten Trambeschaffung war die Planung der benötigten Fahrzeuge korrekt.",
      "end": "Leider kann der Betrieb derzeit nicht wie gewünscht erfolgen."
    },
    {
      "n": 3,
      "start": "Ausschlaggebend ist die Taktverdichtung auf der Linie 8 sowie die drei derzeit nicht",
      "end": "basiert auf einer entsprechenden Bestellung durch den Kanton Basel-Stadt."
    },
    {
      "n": 4,
      "start": "Teilweise kommt es auf der Linie 6, wie auf allen anderen Linien, zu Fahrplanabweichungen.",
      "end": "Als Fahrplan stabilisierende Massnahme wurden Ende August während den Hauptverkehrszeiten die Wendezeiten an den Endhaltestellen erhöht."
    },
    {
      "n": 5,
      "start": "In den Nebenverkehrszeiten sind auf der Linie 6 durchgängig niederflurige Trams vorgesehen.",
      "end": "Aufgrund der erwähnten nicht einsatzfähigen Trams ist dies teilweise nicht möglich."
    },
    {
      "n": 6,
      "start": "Der Gemeinderat hat sich bei den BVB dafür eingesetzt.",
      "end": "Die BVB streben selber bereits einen alternierenden Fahrzeugeinsatz an, können ihn aber aus den genannten betrieblichen Gründen nicht jederzeit garantieren."
    },
    {
      "n": 7,
      "start": "Auch hier stösst die Forderung grundsätzlich auf offene Türen.",
      "end": "Leider kann der Betrieb derzeit nicht wie gewünscht erfolgen."
    }
  ],
  "submitter": "Dr. Petra Priess",
  "co_signatories": [],
  "recommendation": "none",
  "reasoning": {
    "start": "Die BVB sehen selber einen reinen Niederflurbetrieb zu den Nebenverkehrszeiten vor.",
    "end": "Leider kann der Betrieb derzeit nicht wie gewünscht erfolgen."
  }
}
